//! The UniFFI scaffolding.
//!
//! The UDL in `src/stride.udl` is the description of the surface; this
//! generates the Rust side of it. The Kotlin side is generated by
//! `uniffi-bindgen`, which the Gradle build runs.
//!
//! **No file patching.** An earlier version of this script rewrote the
//! generated file to add `#[allow(unsafe_code)]` to each of its
//! `#[unsafe(no_mangle)]` attributes, because the crate used to deny
//! `unsafe` outright. The crate now inherits the workspace's lint table,
//! where `unsafe_code` is `allow` — the workspace's comment says why:
//! "warn" would make unsafe denied everywhere, including this one place.
//!
//! The rule that matters is not a lint but a contract: `unsafe` is allowed
//! **inside this crate and nowhere else**, and
//! `scripts/check-contract-greps.sh` asserts it over the tree. A lint can
//! be silenced with an attribute; a grep cannot.

use std::path::PathBuf;

fn main() {
    // The build script may panic: a build script that fails is a build
    // failure, and there is nobody to show an error to.
    #[allow(clippy::expect_used, clippy::panic)]
    {
        uniffi::generate_scaffolding("src/stride.udl")
            .expect("the UniFFI scaffolding could not be generated");
    }

    // The generated file's path is printed, so cargo knows to rebuild when
    // the UDL changes.
    let out_dir = match std::env::var_os("OUT_DIR") {
        Some(dir) => PathBuf::from(dir),
        None => return,
    };
    println!(
        "cargo:rustc-env=STRIDE_UNIFFI_SCAFFOLDING={}",
        out_dir.join("stride.uniffi.rs").display()
    );
}
